mapper.select:
SELECT
    IFNULL(SUM(amount), 0) AS turnover,
    COUNT(*) AS validOrderCount,
    IFNULL(
        ROUND(
            COUNT(*) * 1.0 / (
                SELECT COUNT(*) FROM orders
                WHERE order_time BETWEEN #{begin} AND #{end}
            ), 2
        ), 0
    ) AS orderCompletionRate,
    IFNULL(
        ROUND(
            IFNULL(SUM(amount), 0) * 1.0 / COUNT(*), 2
        ), 0
    ) AS unitPrice,
    IFNULL(
        (SELECT COUNT(*) FROM user WHERE create_time BETWEEN #{begin} AND #{end}), 0
    ) AS newUsers
FROM orders
WHERE status = 5
AND order_time BETWEEN #{begin} AND #{end}
